  lathe(C, { x, y, prof: [[r * 1.32, h0], [r * 1.05, h0 + h * .2], [r * .72, h0 + h * .55], [r * .42, h0 + h]], n: 4, flat: true, sub: 6, phase: ph, M, scallop: 1.3, blocks: .1 });
