    if (b.sign) { const c = cols[b.s % cols.length], sx = b.x + (b.rot < 0 ? b.w * .35 : -b.w * .3), sh = Math.min(b.h * .7, 30); C.g.fillStyle = css(c, .9); C.g.fillRect(sx - 1.6, topY + 4, 3.2, sh); C.g.fillStyle = 'rgba(0,0,0,.55)'; for (let k = 0; k < sh - 3; k += 4) C.g.fillRect(sx - 1, topY + 6 + k, 2, 1.2); glow(C, sx, topY + 4 + sh / 2, sh, c, .3); }
