/* ================= Estampe (flat print: keylines, flat colour, one red) ================= */
const EST = { ink: '#1c1c22', paper: '#f2ead8', indigo: '#24365a', blue: '#5a7aa0', pale: '#a8bcd0', grey: '#8a8a88', light: '#d8d0bc', green: '#6a8060', red: '#c8342c' };
function inkFill(g, pts, fill, w = 1.4) { poly(g, pts); g.fillStyle = fill; g.fill(); g.strokeStyle = EST.ink; g.lineWidth = w; g.lineJoin = 'round'; g.stroke(); }
function paperGrain(C, seed = 1) { const g = C.g, r = rng(seed); for (let i = 0; i < 2400; i++) { g.fillStyle = r() < .5 ? 'rgba(80,60,30,.05)' : 'rgba(255,255,255,.06)'; g.fillRect(r() * C.W, r() * C.H, 1 + r() * 2, .6); } }
function bokashi(C, top, mid) { const g = C.g; g.fillStyle = EST.paper; g.fillRect(0, 0, C.W, C.H); const gr = g.createLinearGradient(0, 0, 0, C.H * .55); gr.addColorStop(0, top); gr.addColorStop(.35, css(mid, .85)); gr.addColorStop(1, css(mid, 0)); g.fillStyle = gr; g.fillRect(0, 0, C.W, C.H * .55); }
// stylised cloud ribbon (flat, outlined)
function ribbon(C, x, y, w, fill) { const g = C.g, n = Math.round(w / 34); g.beginPath(); g.moveTo(x, y); for (let i = 0; i < n; i++) { const cx = x + (i + .5) * w / n; g.arc(cx, y, w / n / 2, Math.PI, 0); } g.lineTo(x + w, y + 8); g.lineTo(x, y + 8); g.closePath(); g.fillStyle = fill; g.fill(); g.strokeStyle = EST.ink; g.lineWidth = 1.2; g.stroke(); }
function inkIsland(C, cx, cy, rx, depth, seed, topFill) {
  const g = C.g, r = rng(seed), ry = rx * .2; const top = []; for (let i = 0; i < 40; i++) { const t = i / 40 * TAU; top.push([cx + Math.cos(t) * rx * (1 + (r() - .5) * .06), cy + Math.sin(t) * ry]); }
  const under = [[cx - rx, cy]]; for (let i = 1; i < 12; i++) { const t = i / 12; under.push([cx - rx + t * rx * 2 + (r() - .5) * 10, cy + ry + Math.pow(Math.sin(t * Math.PI), .8) * depth * (.7 + r() * .4)]); } under.push([cx + rx, cy]);
  inkFill(g, under, EST.grey, 1.6);
  // strata hatching
  g.save(); poly(g, under); g.clip(); g.strokeStyle = 'rgba(28,28,34,.55)'; g.lineWidth = .8; for (let k = 1; k < 8; k++) { g.beginPath(); for (let i = 0; i <= 30; i++) { const x = cx - rx + i / 30 * rx * 2; g.lineTo(x, cy + ry + k * depth / 8 + Math.sin(i * .7 + k) * 4); } g.stroke(); }
  g.fillStyle = 'rgba(28,28,34,.25)'; g.fillRect(cx + rx * .2, cy, rx, depth * 1.2); g.restore();
  g.save(); poly(g, under); g.clip(); g.strokeStyle = "rgba(28,28,34,.7)"; g.lineWidth = 1; for (let i = 0; i < 18; i++) { const x = cx - rx * .8 + r() * rx * 1.6, y = cy + ry + r() * depth * .5; g.beginPath(); g.moveTo(x, y); g.lineTo(x + (r() - .5) * 6, y + 12 + r() * 20); g.lineTo(x + (r() - .5) * 10, y + 24 + r() * 26); g.stroke(); } g.restore();
  inkFill(g, top, topFill || EST.green, 1.6);
  g.save(); poly(g, top); g.clip(); g.fillStyle = "rgba(30,60,30,.25)"; g.fillRect(cx - rx, cy, rx * 2, ry * 2); g.strokeStyle = "rgba(28,40,28,.6)"; g.lineWidth = .8; for (let i = 0; i < rx * .5; i++) { const a = r() * TAU, d = Math.sqrt(r()) * .9, x = cx + Math.cos(a) * rx * d, y = cy + Math.sin(a) * ry * d; g.beginPath(); g.moveTo(x - 2, y); g.lineTo(x, y - 4); g.lineTo(x + 2, y); g.stroke(); } g.restore();
}
function inkPine(C, x, y, h) { const g = C.g; g.strokeStyle = EST.ink; g.lineWidth = 2; g.beginPath(); g.moveTo(x, y); g.quadraticCurveTo(x + h * .1, y - h * .5, x - h * .05, y - h); g.stroke(); for (let i = 0; i < 4; i++) { const yy = y - h * (.35 + i * .2), w = h * (.36 - i * .07); inkFill(g, [[x - w, yy], [x - w * .4, yy - h * .12], [x + w * .5, yy - h * .1], [x + w, yy], [x + w * .2, yy + h * .03]], '#3a5040', 1.2); } }
