  g.fillStyle = '#f4d48a'; g.fillRect(tx - 32, ry0 - 34, 64, 22); g.strokeStyle = EST.ink; g.lineWidth = .8; for (let x = tx - 32; x <= tx + 32; x += 6) { g.beginPath(); g.moveTo(x, ry0 - 34); g.lineTo(x, ry0 - 12); g.stroke(); } g.strokeRect(tx - 32, ry0 - 34, 64, 22);
  inkFill(g, [[tx - 48, ry0 + 3], [tx + 48, ry0 + 3], [tx + 48, ry0 - 2], [tx - 48, ry0 - 2]], '#5a3a24', 1);
  // roofs: a wide hipped one and a small one, with the bell between
  const roof = (y, w, h) => inkFill(g, [[tx - w - 16, y + 6], [tx - w, y - 4], [tx - w * .35, y - h], [tx + w * .35, y - h], [tx + w, y - 4], [tx + w + 16, y + 6], [tx, y - 2]], EST.indigo, 1.6);
  roof(ry0 - 40, 46, 30);
  inkFill(g, [[tx - 14, ry0 - 70], [tx + 14, ry0 - 70], [tx + 14, ry0 - 92], [tx - 14, ry0 - 92]], '#8a5a38', 1.2);
  inkFill(g, [[tx - 5, ry0 - 72], [tx + 5, ry0 - 72], [tx + 4, ry0 - 86], [tx - 4, ry0 - 86]], '#c8a050', 1);
