    waterPool(C, 470, 512, 50, 12, '#2a4a7a', 3); waterfall(C, 500, I.rimY(500) + 6, 200, 8, '#cfe0ff', 4);
    magTower(C, cx, cy + 6, .82, { stage: 3 });
