    crypt(C, 612, I.rimY(612) + I.soil + I.dAt(612) - 8, .9, 2, OBS.stone2, OBS.slate, OBS.win);
    const ri = islet(C, 1030, 400, 56, 33, { rock: OBS.rock, grass: OBS.grass }, { rootGlow: OBS.magic });
    lightBridge(C, 870, 470, 985, 400, 30, OBS.magic);
