/* ---------- the demo: fly a car around the island ---------- */
function neoPlay7(cv, opt = {}) {
  const W = cv.width, H = cv.height, { cv: back, C: BC } = offC7(W, H);
  neoScene7(BC, { noCars: true });
  const g = cv.getContext('2d'), C = makeC(g, W, H, { L: BC.L }), box = cv.closest('.play');
  const still = window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches;
  const padAt = () => [NEO7.pad[0] + 2, NEO7.pad[1] - 14];
  let kind = opt.kind || 'coupe', [x, y] = padAt(), vx = 0, vy = 0, [tx, ty] = [x, y], face = 1, bank = 0, trail = [], raf = 0;
  const sc = () => (.44 + y / H * .42) * (kind === 'coupe' ? 1 : 1.1);
  const draw = () => { g.setTransform(1, 0, 0, 1, 0, 0); g.drawImage(back, 0, 0); C.glows = []; neoTrail7(g, trail, 2.6); neoCar7(C, x, y, sc(), kind, { face, bank }); flushGlows(C); };
  const tick = () => {
    const dx = tx - x, dy = ty - y, d = Math.hypot(dx, dy), want = Math.min(7.5, d * .07);
    vx += clamp((d > .6 ? dx / d * want : 0) - vx, -.32, .32); vy += clamp((d > .6 ? dy / d * want : 0) - vy, -.32, .32);
    x += vx; y += vy;
    if (Math.abs(vx) > .4) face = vx > 0 ? 1 : -1;
    bank += (clamp(vy * .05, -.3, .3) * face - bank) * .12;
    const s = sc(), tail = (kind === 'coupe' ? 66 : 46) * s;
    if (Math.hypot(vx, vy) > .4) trail.push([x - face * tail * Math.cos(bank), y - face * tail * Math.sin(bank) - 4 * s]); else trail.shift();
    if (trail.length > 40) trail.shift();
    draw();
    raf = (d > .6 || Math.hypot(vx, vy) > .05 || trail.length) ? requestAnimationFrame(tick) : 0;
  };
  const go = (nx, ny) => { tx = clamp(nx, 60, W - 60); ty = clamp(ny, 70, H - 60); if (still) { x = tx; y = ty; vx = vy = 0; trail = []; draw(); return; } if (!raf) raf = requestAnimationFrame(tick); };
  const at = e => { const r = cv.getBoundingClientRect(); return [(e.clientX - r.left) / r.width * W, (e.clientY - r.top) / r.height * H]; };
  let down = false;
  cv.addEventListener('pointerdown', e => { down = true; cv.setPointerCapture && cv.setPointerCapture(e.pointerId); go(...at(e)); });
  cv.addEventListener('pointermove', e => { if (down) go(...at(e)); });
  cv.addEventListener('pointerup', () => { down = false; });
  cv.addEventListener('pointercancel', () => { down = false; });
  cv.addEventListener('keydown', e => { const k = { ArrowLeft: [-50, 0], ArrowRight: [50, 0], ArrowUp: [0, -40], ArrowDown: [0, 40] }[e.key]; if (!k) return; e.preventDefault(); go(tx + k[0], ty + k[1]); });
  if (box) {
    box.querySelectorAll('[data-car]').forEach(b => b.addEventListener('click', () => { kind = b.dataset.car; box.querySelectorAll('[data-car]').forEach(o => o.setAttribute('aria-pressed', String(o === b))); draw(); }));
    const land = box.querySelector('[data-land]'); if (land) land.addEventListener('click', () => go(...padAt()));
  }
  draw();
}

